const query = $input.first().json.query || {};
const status = query.status || 'pending';
const limit = parseInt(query.limit || '20');
const client_id = query.client_id || null;

console.log('PWA API Request — status:', status, 'limit:', limit);

return [{
  json: {
    status,
    limit,
    client_id
  }
}];

const data = $input.first().json;
return [{
  json: {
    type: 'stats',
    pending: data.pending || 0,
    approved: data.approved || 0,
    published: data.published || 0,
    rejected: data.rejected || 0,
    total: data.total || 0,
    daily_post_limit: data.daily_post_limit || 3
  }
}];

const items = $input.all();

if (!items || items.length === 0 || !items[0].json.id) {
  return [{ json: { result: '[]' } }];
}

const posts = items
  .filter(item => item.json && item.json.id)
  .map(item => {
    const p = item.json;
    return {
      id: p.id,
      client_id: p.client_id,
      client_name: p.client_name || '',
      content: p.content || '',
      topic_pillar: p.topic_pillar || 'General',
      post_format: p.post_format || 'text',
      approval_status: p.approval_status,
      post_status: p.post_status,
      approval_note: p.approval_note || null,
      scheduled_for: p.scheduled_for || null,
      estimated_words: parseInt(p.estimated_words) || 0,
      created_at: p.created_at,
      approved_at: p.approved_at || null,
      published_at: p.published_at || null
    };
  });

return [{ json: { result: JSON.stringify(posts) } }];
